  `date` datetime DEFAULT NULL,
  `time` varchar(255) DEFAULT NULL,
  `assessor` varchar(255) DEFAULT NULL,
  `building_type` varchar(255) DEFAULT NULL,
  `property_age` varchar(255) DEFAULT NULL,
  `roof_type` varchar(255) DEFAULT NULL,
  `ceiling_height` varchar(255) DEFAULT NULL,
  `circuit_breaker_spaces` varchar(255) DEFAULT NULL,
  `switch_rating` varchar(255) DEFAULT NULL,
  `phase_type` varchar(255) DEFAULT NULL,
  `distance` float DEFAULT NULL,
  `switchboard_photo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`switchboard_photo`)),
  `vents_total` int(11) DEFAULT NULL,
  `return_air` varchar(255) DEFAULT NULL,
  `zone_controller` varchar(255) DEFAULT NULL,
  `room` varchar(255) DEFAULT NULL,
  `vent_type` varchar(255) DEFAULT NULL,
  `outdoor_location` varchar(255) DEFAULT NULL,
  `ground_surface` varchar(255) DEFAULT NULL,
  `level_surface` varchar(255) DEFAULT NULL,
  `space_available` varchar(255) DEFAULT NULL,
  `outdoor_photos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`outdoor_photos`)),
