  `noise` text DEFAULT NULL,
  `ducting` varchar(255) DEFAULT NULL,
  `ducting_notes` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `agree` tinyint(1) DEFAULT NULL,
  `customer_signature` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`customer_signature`)),
  `assessor_signature` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`assessor_signature`)),
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
